ALTER TABLE "Clases" ADD FOREIGN KEY ("id_asignatura") REFERENCES "Asignaturas" ("id_asignatura") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Clases" ADD FOREIGN KEY ("id_docente") REFERENCES "Usuarios" ("id_usuario") DEFERRABLE INITIALLY IMMEDIATE;

