ALTER TABLE "Matriculas" ADD FOREIGN KEY ("id_clase") REFERENCES "Clases" ("id_clase") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Matriculas" ADD FOREIGN KEY ("id_estado_matricula") REFERENCES "Estado_Matricula" ("id_estado_matricula") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Clases_Horario" ADD FOREIGN KEY ("id_clase") REFERENCES "Clases" ("id_clase") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Clases_Horario" ADD FOREIGN KEY ("id_aula") REFERENCES "Aulas" ("id_aula") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Tareas" ADD FOREIGN KEY ("id_clase") REFERENCES "Clases" ("id_clase") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Tareas_Estudiante" ADD FOREIGN KEY ("id_matricula") REFERENCES "Matriculas" ("id_matricula") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Tareas_Estudiante" ADD FOREIGN KEY ("id_tarea") REFERENCES "Tareas" ("id_tarea") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Tareas_Estudiante" ADD FOREIGN KEY ("id_estado_tarea") REFERENCES "Estado_Tareas" ("id_estado_tarea") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Estudiante_Alerta" ADD FOREIGN KEY ("id_estudiante") REFERENCES "Usuarios" ("id_usuario") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Estudiante_Alerta" ADD FOREIGN KEY ("id_alerta") REFERENCES "Alertas" ("id_alerta") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Participante_Chat" ADD FOREIGN KEY ("id_usuario") REFERENCES "Usuarios" ("id_usuario") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Participante_Chat" ADD FOREIGN KEY ("id_chat") REFERENCES "Chat" ("id_chat") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Mensajes_Chat" ADD FOREIGN KEY ("id_chat") REFERENCES "Chat" ("id_chat") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Mensajes_Chat" ADD FOREIGN KEY ("id_usuario") REFERENCES "Usuarios" ("id_usuario") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Clases_Horario" ADD FOREIGN KEY ("id_dia_semana") REFERENCES "Dia_Semana" ("id_dia_semana") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Tareas" ADD FOREIGN KEY ("creado_por") REFERENCES "Usuarios" ("id_usuario") DEFERRABLE INITIALLY IMMEDIATE;

